/**
 * SkillTutor Anti-Cheat & Authorized Snippet Controller
 * Enforces conceptual articulation and strictly blocks external copy-pasting
 * while allowing authorized hints generated by the inbuilt SkillTutor Copilot.
 */

// In-memory set of authorized snippets for current session
const authorizedSnippets = new Set<string>();

export function registerAuthorizedSnippet(snippet: string) {
  if (!snippet) return;
  const clean = snippet.trim();
  authorizedSnippets.add(clean);
  // Also keep in localStorage for resilience across reloads
  try {
    const existing = JSON.parse(localStorage.getItem('skilltutor_authorized_snippets') || '[]');
    if (!existing.includes(clean)) {
      existing.push(clean);
      localStorage.setItem('skilltutor_authorized_snippets', JSON.stringify(existing.slice(-50)));
    }
  } catch {
    // Ignore storage issues
  }
}

export function isAuthorizedCopilotSnippet(pastedText: string): boolean {
  if (!pastedText) return false;
  const clean = pastedText.trim();

  // Check in-memory set
  if (authorizedSnippets.has(clean)) return true;

  // Check localStorage registry
  try {
    const existing: string[] = JSON.parse(localStorage.getItem('skilltutor_authorized_snippets') || '[]');
    if (existing.some((s) => s === clean || clean.includes(s) || s.includes(clean))) {
      return true;
    }
  } catch {
    // ignore
  }

  // Check if text starts with the official SkillTutor token prefix
  if (clean.startsWith('[Concept]') || clean.startsWith('[SkillTutor Blueprint]')) {
    return true;
  }

  return false;
}

/**
 * Detects if the student entered raw programming language syntax rather than conceptual reasoning.
 */
export function detectCodeBlockPatterns(text: string): { isCode: boolean; reason?: string } {
  if (!text) return { isCode: false };

  const codePatterns = [
    { pattern: /(def\s+[a-zA-Z_]\w*\(|function\s+[a-zA-Z_]|const\s+[a-zA-Z_]+\s*=\s*\([^)]*\)\s*=>)/, reason: 'function definitions' },
    { pattern: /(for\s*\(\s*(let|var|int)\s+[a-zA-Z_]\s*=|while\s*\(.*\)\s*\{)/, reason: 'loop constructs' },
    { pattern: /(public\s+class|class\s+[a-zA-Z_].*\{|import\s+[\w\s{},*]+from)/, reason: 'class or import statements' },
    { pattern: /(cout\s*<<|System\.out\.println|console\.log|printf\()/, reason: 'raw print debugging statements' },
  ];

  for (const { pattern, reason } of codePatterns) {
    if (pattern.test(text)) {
      return {
        isCode: true,
        reason: `Notice: It looks like you pasted or typed ${reason}. SkillTutor measures conceptual mastery. Explain the invariant logic, asymptotic trade-offs, and boundary reasons in plain English.`,
      };
    }
  }

  return { isCode: false };
}
